    pub fn set_diagnostics_selector(buf: &mut [u8; 128], value: CmisDiagnosticsSelector) {
        buf[0] = value.repr() as u8;
    }

    pub fn set_custom_diagnostics_selection(buf: &mut [u8; 128], value: [u8; 2]) {
        buf[2..4].copy_from_slice(&value);
    }
